// `https://admin-shell.io/aas/3/x/AssetInformation/globalAssetId`
// where `x` is the minor version.
//
// NOTE: Constraint AASd-116 is important to enable a generic search across
// global and specific asset IDs (e.g. in IDTA-01002-3-0 discovery
// operations like GetAllAssetLinksById). In the future the constraint
// might become more strict in stating that the name `globalAssetId`
// shall not be used as [ISpecificAssetID.Name].
//
// NOTE: The comparison against `globalAssetId` is ASCII case-insensitive.
//
// Constraint AASd-131:
// For [IAssetInformation] either the [IAssetInformation.GlobalAssetID] shall be
// defined or at least one item in [IAssetInformation.SpecificAssetIDs].
